def validation_row(text, ok=True):
    bg = "#ecfdf3" if ok else "#fff4ed"
    border = "#abefc6" if ok else "#fed7aa"
    icon = "✓" if ok else "!"
    icon_color = "#067647" if ok else "#c2410c"
    html = (
        f'<div style="display:flex;align-items:center;gap:.7rem;background:{bg};border:1px solid {border};'
        f'padding:.72rem .9rem;border-radius:9px;margin:.38rem 0;color:#172033;font-weight:600;">'
        f'<span style="color:{icon_color};font-weight:900;font-size:1.05rem;">{icon}</span>'
        f'<span style="color:#172033;">{text}</span></div>'
    )
    st.markdown(html, unsafe_allow_html=True)


def light_notice(text, tone="info"):
    palette = {
        "info": ("#eff8ff", "#b2ddff", "#1849a9"),
        "success": ("#ecfdf3", "#abefc6", "#067647"),
        "warning": ("#fffaeb", "#fedf89", "#93370d")
    }
    bg, border, accent = palette.get(tone, palette["info"])
    html = (
        f'<div style="background:{bg};border:1px solid {border};padding:.82rem .95rem;'
        f'border-radius:9px;margin:.5rem 0;color:#172033;">'
        f'<span style="color:{accent};font-weight:800;">{text}</span></div>'
    )
    st.markdown(html, unsafe_allow_html=True)

