def _docx_tables(uploaded):
    """Read simple Word tables without requiring python-docx."""
    data = uploaded.getvalue() if hasattr(uploaded, "getvalue") else uploaded.read()
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        root = ET.fromstring(z.read("word/document.xml"))
    ns = {"w": "http://schemas.openxmlformats.org/wordprocessingml/2006/main"}
    tables=[]
    for tbl in root.findall('.//w:tbl', ns):
        rows=[]
        for tr in tbl.findall('./w:tr', ns):
            row=[]
            for tc in tr.findall('./w:tc', ns):
                txt=''.join(t.text or '' for t in tc.findall('.//w:t', ns)).strip()
                row.append(txt)
            if any(x.strip() for x in row): rows.append(row)
        if rows: tables.append(rows)
    return tables


def parse_aerocell_pm_docx(uploaded):
    tables=_docx_tables(uploaded)
    for rows in tables:
        hdr=[x.strip() for x in rows[0]]
        if {'Date','Time','PM1','PM2.5','PM4','PM7','PM10','TSP'}.issubset(set(hdr)):
            df=pd.DataFrame(rows[1:],columns=hdr[:len(rows[0])])
            for c in ['PM1','PM2.5','PM4','PM7','PM10','TSP']:
                df[c]=pd.to_numeric(df[c],errors='coerce')
            df.insert(0,'Sample_ID',[f'AERO-{i+1:03d}' for i in range(len(df))])
            df['Location']='Aerocell monitoring series (GPS linkage not verified)'
